//! The status decoder against what inference-core really emits.
//!
//! `tests/fixtures/inference-core/infer-statuses.json` is generated by
//! inference-core from the code that builds its statuses
//! (`MP_UPDATE_GOLDEN=1 cargo test -p inference-core --lib status_contract`) and
//! lists every way an Infer, CreateEmbedding or modality call can fail on the
//! wire: the gRPC code, the `x-mp-provider-error` kind and the retry timing. It is
//! vendored byte for byte with a sha256 pin, and `scripts/tests/zdr-contract-sync.test.sh`
//! fails when the copy differs from the original. A missing or altered golden
//! FAILS here.
//!
//! Every case in the golden is turned back into a `tonic::Status` exactly as the
//! wire carries it (code, trailers), given a message that spells a DIFFERENT
//! failure, and decoded. A decoder that read the message would be talked into the
//! wrong answer by it.

mod common;

use std::collections::BTreeSet;
use std::time::Duration;

use common::{read_pinned, STATUS_GOLDEN};
use inference_client_rs::{
    Disposition, Failure, InferenceError, Stage, KIND_RATE_LIMITED, KIND_RESIDENCY_UNAVAILABLE,
    KIND_SUBSCRIPTION_USAGE_LIMIT, KIND_TIER_UNAVAILABLE, KIND_TOO_LONG, KIND_TRAILER,
    KIND_ZDR_UNAVAILABLE, RETRY_AFTER_MS_TRAILER, SKIP_RECHECK_AFTER,
};
use serde_json::Value;
use tonic::metadata::{MetadataMap, MetadataValue};
use tonic::{Code, Status};

fn ms(value: u64) -> Option<Duration> {
    Some(Duration::from_millis(value))
}

/// What the client must make of each case in the golden. A case the golden gains
/// that is not in this table fails `the_table_covers_every_case_in_the_golden`.
fn expected() -> Vec<(&'static str, Failure)> {
    let transient = Failure::Transient { retry_after: None };
    let transient_timed = Failure::Transient {
        retry_after: ms(52_260_000),
    };
    vec![
        ("provider_http", transient.clone()),
        ("provider_unavailable", transient.clone()),
        ("provider_subscription_failed", transient.clone()),
        ("provider_invalid_response", Failure::InvalidArgument),
        ("provider_unsupported_model", Failure::Other),
        ("provider_all_exhausted", transient.clone()),
        ("provider_too_long", Failure::TooLong),
        (
            "provider_rate_limited",
            Failure::RateLimited {
                retry_after: ms(1500),
            },
        ),
        ("provider_zdr_unavailable", Failure::ZdrUnavailable),
        (
            "provider_residency_violation",
            Failure::ResidencyUnavailable,
        ),
        ("provider_tier_unavailable", Failure::TierUnavailable),
        (
            "subscription_usage_limit_with_timing",
            Failure::RateLimited {
                retry_after: ms(52_260_000),
            },
        ),
        (
            "subscription_usage_limit_without_timing",
            Failure::RateLimited { retry_after: None },
        ),
        (
            "subscription_reauth_required_with_timing",
            transient_timed.clone(),
        ),
        (
            "subscription_reauth_required_without_timing",
            transient.clone(),
        ),
        (
            "subscription_upstream_unavailable_with_timing",
            transient_timed.clone(),
        ),
        (
            "subscription_upstream_unavailable_without_timing",
            transient.clone(),
        ),
        ("subscription_bad_request_with_timing", transient_timed),
        ("subscription_bad_request_without_timing", transient),
        ("modality_refused_under_zdr", Failure::ZdrUnavailable),
        ("embedding_zdr_unavailable", Failure::ZdrUnavailable),
        (
            "embedding_residency_unavailable",
            Failure::ResidencyUnavailable,
        ),
        ("embedding_tier_unavailable", Failure::TierUnavailable),
        ("embedding_provider_http", Failure::Internal),
    ]
}

struct WireCase {
    id: String,
    code: Code,
    trailers: Vec<(String, String)>,
}

fn golden() -> Value {
    read_pinned(STATUS_GOLDEN)
}

fn wire_cases(golden: &Value) -> Vec<WireCase> {
    golden["cases"]
        .as_array()
        .expect("cases")
        .iter()
        .map(|case| WireCase {
            id: case["id"].as_str().expect("id").to_owned(),
            code: Code::from_i32(
                i32::try_from(case["grpc_code_number"].as_i64().expect("code number"))
                    .expect("code fits"),
            ),
            trailers: case["trailers"]
                .as_object()
                .expect("trailers")
                .iter()
                .map(|(key, value)| (key.clone(), value.as_str().expect("trailer").to_owned()))
                .collect(),
        })
        .collect()
}

/// The status as it arrives: trailers in the metadata, and a message that names a
/// different failure from the one the trailers carry.
fn as_received(case: &WireCase, misleading_message: &str) -> Status {
    let mut metadata = MetadataMap::new();
    for (key, value) in &case.trailers {
        metadata.insert(
            tonic::metadata::MetadataKey::from_bytes(key.as_bytes()).expect("trailer key"),
            MetadataValue::try_from(value.as_str()).expect("trailer value"),
        );
    }
    Status::with_metadata(case.code, misleading_message, metadata)
}

#[test]
fn the_table_covers_every_case_in_the_golden() {
    let golden = golden();
    let in_golden: BTreeSet<String> = wire_cases(&golden)
        .into_iter()
        .map(|case| case.id)
        .collect();
    let in_table: BTreeSet<String> = expected()
        .into_iter()
        .map(|(id, _)| id.to_owned())
        .collect();
    assert_eq!(
        in_golden, in_table,
        "inference-core's golden and this client's expectations must list the same cases; \
         decide what the client does with the new one"
    );
}

#[test]
fn every_case_decodes_to_what_the_client_must_do_with_it() {
    let golden = golden();
    let table = expected();
    for case in wire_cases(&golden) {
        let (_, want) = table
            .iter()
            .find(|(id, _)| *id == case.id)
            .unwrap_or_else(|| panic!("{} has no expectation", case.id));
        // A message that says "the service is unavailable, retry" on every case:
        // right for none of the typed refusals.
        let decoded = InferenceError::from_status(&as_received(
            &case,
            "service temporarily unavailable, please retry",
        ));
        assert_eq!(decoded.failure(), want, "{}", case.id);
        assert_eq!(decoded.stage(), Stage::Call, "{}", case.id);
        assert_eq!(decoded.code(), Some(case.code), "{}", case.id);
        let kind_on_wire = case
            .trailers
            .iter()
            .find(|(key, _)| key == KIND_TRAILER)
            .map(|(_, value)| value.as_str());
        assert_eq!(decoded.wire_kind(), kind_on_wire, "{}", case.id);
    }
}

#[test]
fn the_decision_does_not_depend_on_the_message_at_all() {
    let golden = golden();
    let messages = [
        "",
        "zdr_unavailable",
        "no deployment has a verified zero data retention contract",
        "rate limited, retry after 5s",
        "too_long",
        "internal error",
        "permission denied",
    ];
    for case in wire_cases(&golden) {
        let baseline = InferenceError::from_status(&as_received(&case, ""))
            .failure()
            .clone();
        for message in messages {
            let decoded = InferenceError::from_status(&as_received(&case, message));
            assert_eq!(
                decoded.failure(),
                &baseline,
                "{}: the message {message:?} changed the decision",
                case.id
            );
        }
    }
}

#[test]
fn a_refusal_to_send_is_never_a_retry() {
    // The asymmetry the whole decoder is built around: a posture refusal retried
    // into another route sends content the organization said must not leave.
    let golden = golden();
    let mut refusals = 0;
    for case in wire_cases(&golden) {
        let decoded = InferenceError::from_status(&as_received(&case, ""));
        if matches!(
            decoded.failure(),
            Failure::ZdrUnavailable | Failure::ResidencyUnavailable | Failure::TierUnavailable
        ) {
            refusals += 1;
            assert_eq!(
                decoded.disposition(),
                Disposition::Skip {
                    recheck_after: SKIP_RECHECK_AFTER
                },
                "{}",
                case.id
            );
        }
    }
    assert_eq!(refusals, 7, "the golden's refusal cases changed");
}

#[test]
fn every_kind_the_golden_lists_is_one_the_client_has_met() {
    let golden = golden();
    let listed: BTreeSet<String> = golden["kinds"]
        .as_array()
        .expect("kinds")
        .iter()
        .map(|kind| kind.as_str().expect("kind").to_owned())
        .collect();
    let used: BTreeSet<String> = wire_cases(&golden)
        .into_iter()
        .flat_map(|case| case.trailers)
        .filter(|(key, _)| key == KIND_TRAILER)
        .map(|(_, value)| value)
        .collect();
    assert_eq!(
        listed, used,
        "the golden lists a kind no case uses, or the reverse"
    );

    let named_by_the_client: BTreeSet<String> = [
        KIND_RATE_LIMITED,
        KIND_RESIDENCY_UNAVAILABLE,
        KIND_SUBSCRIPTION_USAGE_LIMIT,
        KIND_TIER_UNAVAILABLE,
        KIND_TOO_LONG,
        KIND_ZDR_UNAVAILABLE,
    ]
    .into_iter()
    .map(str::to_owned)
    .collect();
    // The kinds the client does not name are decoded by their code, on purpose:
    // the three subscription refusals other than the usage limit.
    let by_code_only: BTreeSet<String> = listed.difference(&named_by_the_client).cloned().collect();
    assert_eq!(
        by_code_only,
        [
            "subscription_bad_request",
            "subscription_reauth_required",
            "subscription_upstream_unavailable"
        ]
        .into_iter()
        .map(str::to_owned)
        .collect::<BTreeSet<_>>(),
        "a new kind arrived in the golden: name it in the client or decide it is read by code"
    );
}

#[test]
fn the_trailer_keys_are_the_ones_inference_core_sends() {
    let golden = golden();
    assert_eq!(golden["trailer_keys"]["kind"], KIND_TRAILER);
    assert_eq!(
        golden["trailer_keys"]["retry_after_ms"],
        RETRY_AFTER_MS_TRAILER
    );
}

#[test]
fn the_codes_in_the_golden_are_the_numbers_tonic_decodes() {
    // The golden writes each code twice, by name and by number; a mismatch would
    // mean the vendored file was edited or tonic's numbering moved.
    let golden = golden();
    for case in golden["cases"].as_array().expect("cases") {
        let name = case["grpc_code"].as_str().expect("code name");
        let number =
            i32::try_from(case["grpc_code_number"].as_i64().expect("number")).expect("fits");
        let normalised = |text: &str| text.replace('_', "").to_ascii_lowercase();
        assert_eq!(
            normalised(&format!("{:?}", Code::from_i32(number))),
            normalised(name),
            "{}",
            case["id"]
        );
    }
}

#[test]
fn a_status_from_an_inference_core_that_predates_the_trailers_is_terminal() {
    // FAILED_PRECONDITION with a message and no kind: how a ZDR refusal looked
    // before the trailers existed. It cannot be told from any other precondition
    // without reading the message, so it is neither retried nor sent on.
    let legacy = Status::failed_precondition(
        "no deployment has a verified zero data retention contract for this request",
    );
    let decoded = InferenceError::from_status(&legacy);
    assert_eq!(decoded.failure(), &Failure::Other);
    assert_eq!(decoded.disposition(), Disposition::Terminal);
}
